-- create "verification_cases" table
CREATE TABLE "verification_cases" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "profile_id" uuid NOT NULL, "account_id" uuid NOT NULL, "color" character varying NOT NULL, "subscription_id" character varying NOT NULL, "plan_code" character varying NOT NULL DEFAULT '', "payment_channel" character varying NOT NULL DEFAULT '', "status" character varying NOT NULL DEFAULT 'awaiting_consent', "refund_status" character varying NOT NULL DEFAULT 'not_applicable', "consent_version" character varying NOT NULL DEFAULT '', "consent_at" timestamptz NULL, "smile_job_id" character varying NULL, "smile_reference" character varying NOT NULL DEFAULT '', "smile_product" character varying NOT NULL DEFAULT '', "smile_result_code" character varying NOT NULL DEFAULT '', "document_type" character varying NOT NULL DEFAULT '', "document_country" character varying NOT NULL DEFAULT '', "liveness_result" character varying NOT NULL DEFAULT 'pending', "document_result" character varying NOT NULL DEFAULT 'pending', "face_match_result" character varying NOT NULL DEFAULT 'pending', "database_result" character varying NOT NULL DEFAULT 'pending', "face_match_confidence" double precision NOT NULL DEFAULT 0, "name_match_score" double precision NOT NULL DEFAULT 0, "trust_score" bigint NOT NULL DEFAULT 0, "eligible_at_payment" boolean NOT NULL DEFAULT false, "document_fingerprint" character varying NOT NULL DEFAULT '', "decision_reasons" jsonb NOT NULL, "fraud_signals" jsonb NOT NULL, "decision_reason" character varying NOT NULL DEFAULT '', "decided_by_name" character varying NOT NULL DEFAULT '', "decided_at" timestamptz NULL, "verified_at" timestamptz NULL, "callback_count" bigint NOT NULL DEFAULT 0, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "verification_cases_subscription_id_key" to table: "verification_cases"
CREATE UNIQUE INDEX "verification_cases_subscription_id_key" ON "verification_cases" ("subscription_id");
-- create index "verification_cases_smile_job_id_key" to table: "verification_cases"
CREATE UNIQUE INDEX "verification_cases_smile_job_id_key" ON "verification_cases" ("smile_job_id");
-- create index "verificationcase_status_created_at" to table: "verification_cases"
CREATE INDEX "verificationcase_status_created_at" ON "verification_cases" ("status", "created_at");
-- create index "verificationcase_profile_id_status" to table: "verification_cases"
CREATE INDEX "verificationcase_profile_id_status" ON "verification_cases" ("profile_id", "status");
-- create index "verificationcase_document_fingerprint" to table: "verification_cases"
CREATE INDEX "verificationcase_document_fingerprint" ON "verification_cases" ("document_fingerprint");
-- create "verification_eligibilities" table
CREATE TABLE "verification_eligibilities" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "profile_id" uuid NOT NULL, "account_id" uuid NOT NULL, "color" character varying NOT NULL, "state" character varying NOT NULL DEFAULT 'assessed', "tier" character varying NOT NULL DEFAULT 'request', "trust_score" bigint NOT NULL DEFAULT 0, "reasons" jsonb NOT NULL, "score_source" character varying NOT NULL DEFAULT '', "requested_at" timestamptz NULL, "last_checked_at" timestamptz NULL, "next_check_at" timestamptz NULL, "notified_at" timestamptz NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "verificationeligibility_profile_id" to table: "verification_eligibilities"
CREATE UNIQUE INDEX "verificationeligibility_profile_id" ON "verification_eligibilities" ("profile_id");
-- create index "verificationeligibility_state_next_check_at" to table: "verification_eligibilities"
CREATE INDEX "verificationeligibility_state_next_check_at" ON "verification_eligibilities" ("state", "next_check_at");
